  static var serviceDescriptor: GRPCServiceDescriptor { get }
  var interceptors: Whetherlabs_Review_V1_ReviewServiceServerInterceptorFactoryProtocol? { get }

  /// RateBook rates a book (0-5 stars, half-star increments).
  /// Automatically adds book to "read" shelf.
  func rateBook(
    request: Whetherlabs_Review_V1_RateBookRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Whetherlabs_Review_V1_RateBookResponse

  /// ReviewBook creates or updates a review for a book.
  func reviewBook(
    request: Whetherlabs_Review_V1_ReviewBookRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Whetherlabs_Review_V1_ReviewBookResponse

  /// GetMyReview gets the authenticated user's review for a book.
  func getMyReview(
    request: Whetherlabs_Review_V1_GetMyReviewRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Whetherlabs_Review_V1_GetMyReviewResponse

  /// DeleteReview deletes the authenticated user's review for a book.
  func deleteReview(
    request: Whetherlabs_Review_V1_DeleteReviewRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Whetherlabs_Review_V1_DeleteReviewResponse

  /// GetBookReviews gets public reviews for a book.
  func getBookReviews(
    request: Whetherlabs_Review_V1_GetBookReviewsRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Whetherlabs_Review_V1_GetBookReviewsResponse

  /// GetUserReviews gets all reviews by a user.
  func getUserReviews(
    request: Whetherlabs_Review_V1_GetUserReviewsRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Whetherlabs_Review_V1_GetUserReviewsResponse
}

